{
  "name": "Cobolt 06-01系列激光器",
  "name_en": "Cobolt 06-01 Series Laser",
  "manufacturer": "Cobolt",
  "description": "Cobolt 06-01系列是一类实验室激光器，可提供稳定激光输出，并支持恒功率、恒电流及数字/模拟调制控制。该类设备常用于光学实验、激发光源、光路对准和各类测量场景。",
  "description_en": "The Cobolt 06-01 Series is a family of laboratory lasers that provides stable laser output and supports constant-power, constant-current, and digital/analog modulation control. These devices are commonly used for optical experiments, excitation, beam alignment, and measurement applications.",
  "tag_hints": [
    "lab laser source",
    "constant power control",
    "constant current control",
    "digital modulation",
    "analog modulation",
    "optical excitation",
    "beam alignment",
    "interlock safety"
  ],
  "actions": [
    {
      "action_name": "auto-clear_fault_async",
      "description": "清除设备故障状态",
      "description_en": "Clear the device fault state"
    },
    {
      "action_name": "auto-enter_mod_mode_async",
      "description": "进入调制模式",
      "description_en": "Enter modulation mode"
    },
    {
      "action_name": "auto-initialize",
      "description": "初始化激光器",
      "description_en": "Initialize the laser"
    },
    {
      "action_name": "auto-restart_async",
      "description": "强制重新启动激光输出",
      "description_en": "Force a restart of laser emission"
    },
    {
      "action_name": "auto-idn",
      "description": "获取序列号",
      "description_en": "Get the serial number"
    },
    {
      "action_name": "auto-ksw_enabled",
      "description": "获取/设置钥匙开关使能状态",
      "description_en": "Get/set the key switch enable state"
    },
    {
      "action_name": "auto-enabled",
      "description": "获取/设置激光输出使能状态",
      "description_en": "Get/set the laser emission enable state"
    },
    {
      "action_name": "auto-autostart",
      "description": "获取/设置自动启动状态",
      "description_en": "Get/set the autostart state"
    },
    {
      "action_name": "auto-restart",
      "description": "强制重新启动激光输出",
      "description_en": "Force a restart of laser emission"
    },
    {
      "action_name": "auto-operating_hours",
      "description": "获取激光头累计工作时间",
      "description_en": "Get the laser head operating hours"
    },
    {
      "action_name": "auto-interlock",
      "description": "获取联锁状态",
      "description_en": "Get the interlock state"
    },
    {
      "action_name": "auto-ctl_mode",
      "description": "获取/设置控制模式",
      "description_en": "Get/set the control mode"
    },
    {
      "action_name": "auto-current_sp",
      "description": "获取/设置驱动电流设定值",
      "description_en": "Get/set the drive current setpoint"
    },
    {
      "action_name": "auto-power_sp",
      "description": "获取/设置输出功率设定值",
      "description_en": "Get/set the output power setpoint"
    },
    {
      "action_name": "auto-power",
      "description": "获取输出功率",
      "description_en": "Get the output power"
    },
    {
      "action_name": "auto-status",
      "description": "获取故障状态",
      "description_en": "Get the fault status"
    },
    {
      "action_name": "auto-clear_fault",
      "description": "清除设备故障状态",
      "description_en": "Clear the device fault state"
    },
    {
      "action_name": "auto-enter_mod_mode",
      "description": "进入调制模式",
      "description_en": "Enter modulation mode"
    },
    {
      "action_name": "auto-digital_mod",
      "description": "获取/设置数字调制使能状态",
      "description_en": "Get/set the digital modulation enable state"
    },
    {
      "action_name": "auto-analog_mod",
      "description": "获取/设置模拟调制使能状态",
      "description_en": "Get/set the analog modulation enable state"
    },
    {
      "action_name": "auto-analogli_mod",
      "description": "获取/设置模拟LI调制使能状态",
      "description_en": "Get/set the analog LI modulation enable state"
    },
    {
      "action_name": "auto-mod_mode",
      "description": "获取当前调制模式",
      "description_en": "Get the current modulation mode"
    }
  ]
}

